// Convention-based: scoped DbContext goes on InvokeAsync
public sealed class AuditMiddleware(RequestDelegate next)
{
    public async Task InvokeAsync(HttpContext context, AppDbContext db)
    {
        await next(context);
        db.Audits.Add(new Audit(context.Request.Path, context.Response.StatusCode));
        await db.SaveChangesAsync(context.RequestAborted);
    }
}

// Factory-based: constructor injection of scoped services is fine
public sealed class TenantMiddleware(ITenantStore store) : IMiddleware
{
    public async Task InvokeAsync(HttpContext context, RequestDelegate next)
    {
        context.Items["tenant"] = await store.FindAsync(context.Request.Host.Host);
        await next(context);
    }
}

