public sealed class TimingFilter(ILogger<TimingFilter> log) : IAsyncActionFilter
{
    public async Task OnActionExecutionAsync(ActionExecutingContext ctx, ActionExecutionDelegate next)
    {
        var sw = Stopwatch.StartNew();
        var executed = await next();               // the action runs here
        log.LogInformation("{Action} took {Ms} ms", ctx.ActionDescriptor.DisplayName, sw.ElapsedMilliseconds);
    }
}

