[HttpPut("{id:int}")]
public async Task<IActionResult> Update(int id, UpdateTask dto, [FromHeader(Name = "If-Match")] string? ifMatch)
{
    if (ifMatch is null) return StatusCode(StatusCodes.Status428PreconditionRequired);
    var task = await _db.Tasks.FindAsync(id);
    if (task is null) return NotFound();

    _db.Entry(task).Property(t => t.RowVersion).OriginalValue = Convert.FromBase64String(ifMatch.Trim('"'));
    task.Title = dto.Title;
    try { await _db.SaveChangesAsync(); }
    catch (DbUpdateConcurrencyException) { return StatusCode(StatusCodes.Status412PreconditionFailed); }

    Response.Headers.ETag = $"\"{Convert.ToBase64String(task.RowVersion)}\"";
    return NoContent();
}

app.MapPost("/payments", async (CreatePayment cmd, [FromHeader(Name = "Idempotency-Key")] string? key,
                                IIdempotencyStore store, IPaymentService payments) =>
{
    if (string.IsNullOrWhiteSpace(key)) return Results.Problem("Idempotency-Key is required.", statusCode: 400);

    var fingerprint = Fingerprint.Of(cmd);
    var existing = await store.TryBeginAsync(key, fingerprint);   // unique index on key
    if (existing is { InProgress: true }) return Results.Conflict();
    if (existing is { Fingerprint: var f } && f != fingerprint) return Results.UnprocessableEntity();
    if (existing is { Response: { } saved }) return saved.ToResult();

    var result = await payments.CreateAsync(cmd);
    await store.CompleteAsync(key, result);
    return result.ToResult();
});

